      "en": "A spin-on fuel filter with StrataPore® media: it efficiently traps harmful contaminants, protects injectors and fuel-system components, and keeps a clean fuel flow for stable engine operation. Meets or exceeds OE requirements; the spin-on design makes servicing and replacement easier."
