      "en": "A high-efficiency lube filter that protects the engine from harmful contaminants while keeping oil flowing freely and the engine running reliably. StrataPore® media delivers high cleaning efficiency and helps reduce wear and deposits. Designed for low oil-flow restriction and high filtration efficiency; meets or exceeds OE requirements."
