      "kk": "Бұралмалы май сүзгісі толық ағынды және байпастық сүзуді біріктіреді: зиянды ластануларды жояды және оңтайлы май ағынын сақтап, қозғалтқышты қорғайды және оның қызмет мерзімін ұзартады. Ағынға төмен кедергі мен жоғары тазарту тиімділігі қозғалтқыш пен майдың ресурсын ұзартуға көмектеседі. OE талаптарына сай келеді немесе одан асып түседі.",
      "en": "A spin-on lube filter that combines full-flow and bypass filtration: it removes harmful contaminants and keeps oil flow optimal, protecting the engine and extending its life. Low flow restriction and high cleaning efficiency help extend both engine and oil life. Meets or exceeds OE requirements."
