    "summary": {
      "ru": "Универсальное моторное масло для высоконагруженных дизельных двигателей с технологией Mid SAPS (среднее содержание сульфатной золы, фосфора и серы). Обеспечивает чистоту двигателя, защиту от износа и стабильность свойств. Подходит для дизельных и бензиновых двигателей, в том числе оснащённых системами рециркуляции отработавших газов (EGR) и сажевыми фильтрами (DPF).",
      "kk": "Mid SAPS технологиясы бар (сульфатты күл, фосфор және күкірттің орташа мөлшері) жоғары жүктемелі дизельдік қозғалтқыштарға арналған әмбебап мотор майы. Қозғалтқыштың тазалығын, тозудан қорғауды және қасиеттерінің тұрақтылығын қамтамасыз етеді. Дизельдік және бензинді қозғалтқыштарға, соның ішінде пайдаланылған газдарды рециркуляциялау (EGR) жүйелері мен күйе сүзгілері (DPF) бар қозғалтқыштарға жарамды.",
      "en": "A universal engine oil for heavily loaded diesel engines with Mid SAPS technology (medium sulphated ash, phosphorus and sulphur). It keeps the engine clean, protects against wear and holds its properties stable. Suitable for diesel and petrol engines, including those with exhaust gas recirculation (EGR) and diesel particulate filters (DPF)."
    },
