          "ru": "Спецтехника, Сельхозтехника, Грузовики и автобусы",
          "kk": "Арнайы техника, Ауыл шаруашылығы техникасы, Жүк көліктері мен автобустар",
          "en": "Heavy machinery, Agricultural machinery, Trucks and buses"
